35: /** destroy() also waits on an in-flight stopAsync, so it needs its own ceiling. */
36: const DESTROY_TIMEOUT_MS = 2_000;
37: /** A store write in flight must land before the session header is closed. */
38: const DRAIN_TIMEOUT_MS = 3_000;
39: /** Enough detail for the 420 px preview without upscaling; measured camera frames are unchanged. */
40: const PREVIEW_WIDTH = 640;
41: /** About twelve preview frames a second is enough to aim with. */
42: const PREVIEW_INTERVAL_MS = 80;
