44: export interface CaptureEvents {
45:   onSamples(samples: PulseSample[]): void | Promise<void>;
46:   onValidation(message: ValidationMessage): void;
47:   onError(error: SdkError): void;
48:   onPreview(frame: PreviewFrame): void;
49: }
