55: export function startCapture(input: {
56:   apiKey: string;
57:   anchor: SessionAnchor;
58:   events: CaptureEvents;
59: }): CaptureSession {
60:   const sdk = new SmartSpectraSDK({
61:     apiKey: input.apiKey,
62:     // The whole cardio bundle, deliberately. Requesting PULSE_RATE alone produced no metrics at
63:     // all across full sessions, while the bundle produced a pulse series on this same machine.
64:     requestedMetrics: [...cardioMetrics],
65:     // Session summaries would leave the machine; ChessPulse is local-only.
66:     enableTelemetry: false,
67:     logLevel: SmartSpectraLogLevel.kWarning,
