70:   let lastTUs = input.anchor.monoUs;
71:   let timer: NodeJS.Timeout | undefined;
72:   let closed = false;
73:   let stopping: Promise<void> | undefined;
74:   let terminalReported = false;
75:   const writes = new Set<Promise<void>>();
76:   let lastPreviewAt = 0;
77:   let previewErrorReported = false;
78: 
79:   function flush(): void {
80:     if (timer !== undefined) {
81:       clearTimeout(timer);
82:       timer = undefined;
83:     }
84:     if (pending.length === 0) return;
85:     const batch = pending;
86:     pending = [];
87:     let run: void | Promise<void>;
88:     try {
89:       run = input.events.onSamples(batch);
90:     } catch {
91:       void Promise.resolve().then(() => shutdown());
92:       return;
93:     }
94:     if (!run || typeof run.then !== 'function') return;
95:     // Tracked so the stop path can wait for the tail to reach the store before the header closes.
96:     const write = run;
97:     writes.add(write);
98:     void write.then(
99:       () => {
100:         writes.delete(write);
101:       },
102:       () => {
103:         // A refused batch means the session is gone; release the camera with it.
104:         writes.delete(write);
105:         void shutdown();
106:       },
107:     );
108:   }
109: 
110:   function emitError(error: SdkError): void {
111:     if (closed) return;
112:     if (!error.retryable) terminalReported = true;
113:     input.events.onError(error);
114:   }
115: 
116:   function shutdown(): Promise<void> {
117:     if (stopping) return stopping;
118:     closed = true;
119:     stopping = Promise.resolve().then(async () => {
120:       flush();
121:       try {
122:         await beforeDeadline(sdk.stopAsync(), STOP_TIMEOUT_MS);
123:       } catch {
124:         // The pipeline is already gone. destroy() below still releases the camera handle.
125:       }
126:       try {
127:         // destroy() awaits the same stopAsync promise when one is in flight, so it needs a ceiling too.
128:         await beforeDeadline(sdk.destroy(), DESTROY_TIMEOUT_MS);
129:       } catch {
130:         // Nothing is left to release.
131:       }
132:       if (writes.size > 0) {
133:         try {
134:           await beforeDeadline(
135:             Promise.allSettled([...writes]).then(() => undefined),
136:             DRAIN_TIMEOUT_MS,
137:           );
138:         } catch {
139:           // A wedged write is abandoned; the samples already in the file stay valid.
140:         }
141:       }
142:     });
143:     return stopping;
144:   }
145: 
146:   sdk.on('metrics', (buffer) => {
147:     if (closed) return;
148:     let payload: unknown;
149:     try {
150:       payload = decodeMetrics(buffer);
151:     } catch (error) {
152:       debug('metrics decode failed', error instanceof Error ? error.message : error);
153:       return;
154:     }
155:     const fresh = newPulseSamples(payload, input.anchor, lastTUs);
156:     if (DEBUG) {
157:       const series = (payload as { cardio?: { pulseRate?: unknown[] } } | null)?.cardio?.pulseRate;
158:       const last = Array.isArray(series) ? series[series.length - 1] : undefined;
159:       debug(
160:         'metrics',
161:         { series: Array.isArray(series) ? series.length : 0, fresh: fresh.length, last, lastTUs },
162:       );
163:     }
164:     if (fresh.length === 0) return;
165:     lastTUs = fresh[fresh.length - 1].tUs;
166:     pending.push(...fresh);
167:     if (timer === undefined) timer = setTimeout(flush, FLUSH_MS);
168:   });
169: 
170:   sdk.on('validationStatus', (code, timestampUs, hint) => {
171:     if (closed) return;
172:     debug('validation', code, JSON.stringify(hint));
173:     const message = validationMessage(code, timestampUs, hint, input.anchor);
174:     if (message) input.events.onValidation(message);
175:   });
176: 
177:   sdk.on('videoOutput', (buffer, width, height, stride) => {
178:     if (closed) return;
179:     const now = Date.now();
180:     if (now - lastPreviewAt < PREVIEW_INTERVAL_MS) return;
181:     lastPreviewAt = now;
182:     try {
183:       input.events.onPreview(downscaleRgbToRgba(buffer, width, height, stride, PREVIEW_WIDTH));
184:     } catch (error) {
185:       if (previewErrorReported) return;
186:       previewErrorReported = true;
187:       debug('preview frame rejected', error instanceof Error ? error.message : error);
188:     }
189:   });
190: 
191:   sdk.on('error', (code, message, retryable) => {
192:     emitError({ code, message: sdkErrorMessage(code, message), retryable });
193:     if (!retryable) void shutdown();
194:   });
195: 
196:   sdk.on('processingStatus', (status) => {
197:     if (status !== ProcessingStatus.kError) return;
198:     // A retryable error may have been reported without a terminal one; the status is still terminal.
199:     if (!terminalReported) {
200:       emitError({
201:         code: SmartSpectraErrorCode.kProcessingFailed,
202:         message: sdkErrorMessage(SmartSpectraErrorCode.kProcessingFailed, ''),
203:         retryable: false,
204:       });
205:     }
206:     void shutdown();
207:   });
208: 
209:   // The SDK owns the camera. Feeding it frames from the page instead produced no metrics at all
210:   // on this machine, while this path measured a pulse series.
211:   sdk.useCamera(CameraSelection.default);
212:   try {
213:     sdk.start();
214:   } catch (error) {
215:     closed = true;
216:     void sdk.destroy().catch(() => undefined);
217:     throw new Error(sdkErrorMessage(errorCode(error), errorText(error)));
218:   }
219: 
220:   return { stop: shutdown };
221: }
222: 
223: function errorCode(error: unknown): number {
224:   if (typeof error === 'object' && error !== null && 'code' in error) {
225:     const code = (error as { code?: unknown }).code;
226:     if (typeof code === 'number') return code;
227:   }
228:   return SmartSpectraErrorCode.kProcessingFailed;
229: }
230: 
231: function errorText(error: unknown): string {
232:   return error instanceof Error ? error.message : '';
233: }
234: 
235: function beforeDeadline(work: Promise<void>, ms: number): Promise<void> {
236:   return new Promise((resolve, reject) => {
237:     const timer = setTimeout(() => reject(new Error('The sensing pipeline did not stop in time.')), ms);
238:     timer.unref();
239:     work.then(
240:       () => {
241:         clearTimeout(timer);
242:         resolve();
243:       },
244:       (error: unknown) => {
245:         clearTimeout(timer);
246:         reject(error);
247:       },
248:     );
249:   });
250: }

