39:   // Only the custom provider may redirect the key; OpenCode Go has one fixed endpoint.
40:   const configuredBase = provider === 'custom' ? env.CP_AI_BASE_URL?.trim() ?? '' : '';
41:   const baseUrl = configuredBase || (provider === 'custom' ? '' : DEFAULT_BASE_URL[provider]);
42:   if (!baseUrl) {
43:     return { disabled: true, reason: 'CP_AI_BASE_URL is required for a custom provider. The AI reading stays off.' };
44:   }
