215: async function scoreAlignedMoves(
216:   games: readonly {
217:     game: {
218:       index: number;
219:       moves: { san: string; clockSec?: number }[];
220:       timeControl?: string;
221:       includeInStats: boolean;
222:     };
223:   }[],
224:   moveTimes: readonly { gameIndex: number; moveIndex: number; tUs: number | null }[],
225:   samples: readonly PulseSample[],
226:   baseline: number,
227:   engine: Evaluator,
228: ): Promise<{
229:   metrics: MoveMetric[];
230:   elevatedBlunderTimes: (number | null)[];
231:   timelineMoves: TimelineMove[];
232: }> {
233:   const cache = new Map<string, Promise<PositionEval>>();
234:   const evaluate = (fen: string): Promise<PositionEval> => {
235:     const cached = cache.get(fen);
236:     if (cached) return cached;
237:     const pending = engine.evaluate(fen);
238:     cache.set(fen, pending);
239:     return pending;
240:   };
241:   const metrics: MoveMetric[] = [];
242:   const elevatedBlunderTimes: (number | null)[] = [];
243:   const timelineMoves: TimelineMove[] = [];
244:   for (const aligned of games) {
245:     if (!aligned.game.includeInStats) continue;
246:     const sans = aligned.game.moves.map((move) => move.san);
247:     const thinks = thinkTimeSec(aligned.game);
248:     const positions = positionsFromMoves(sans);
249:     for (let moveIndex = 0; moveIndex < sans.length; moveIndex += 1) {
250:       const position = positions[moveIndex];
251:       if (!position || position.illegal || !position.fenAfter) {
252:         for (let rest = moveIndex; rest < sans.length; rest += 1) {
253:           const when = moveTimes.find((time) => time.gameIndex === aligned.game.index && time.moveIndex === rest);
254:           const rawThink = thinks[rest] ?? null;
255:           metrics.push({
256:             cpl: null,
257:             accuracy: null,
258:             blunder: false,
259:             band: null,
260:             includeInStats: true,
261:           });
262:           timelineMoves.push({
263:             gameIndex: aligned.game.index,
264:             moveIndex: rest,
265:             san: sans[rest] ?? '',
266:             tUs: when?.tUs ?? null,
267:             cpl: null,
268:             thinkSec: rawThink !== null && rawThink >= 0 ? rawThink : null,
269:             blunder: false,
270:             band: null,
271:           });
272:         }
273:         break;
274:       }
275:       const when = moveTimes.find((time) => time.gameIndex === aligned.game.index && time.moveIndex === moveIndex);
276:       const before = await evaluate(position.fenBefore);
277:       const after = await evaluate(position.fenAfter);
278:       const band = when?.tUs === undefined || when.tUs === null ? null : bandAt(samples, when.tUs, baseline);
279:       const metric = scoreMove(before, after, band, aligned.game.includeInStats);
280:       if (metric.blunder && metric.band === 'elevated') elevatedBlunderTimes.push(when?.tUs ?? null);
281:       metrics.push(metric);
282:       const rawThink = thinks[moveIndex] ?? null;
283:       timelineMoves.push({
284:         gameIndex: aligned.game.index,
285:         moveIndex,
286:         san: sans[moveIndex] ?? '',
287:         tUs: when?.tUs ?? null,
288:         cpl: metric.cpl,
289:         thinkSec: rawThink !== null && rawThink >= 0 ? rawThink : null,
290:         blunder: metric.blunder,
291:         band: metric.band,
292:       });
293:     }
294:   }
295:   return { metrics, elevatedBlunderTimes, timelineMoves };
296: }
