308: export function elevatedClaim(
309:   samples: readonly PulseSample[],
310:   startUs: number,
311:   stopUs: number,
312:   baseline: number,
313:   blunderTimes: readonly (number | null)[],
314: ): { elevatedMinutes: number; deltaBpm: number } | undefined {
315:   if (blunderTimes.length === 0 || blunderTimes.some((time) => time === null)) return undefined;
316:   const periods = elevatedPeriods(samples, startUs, stopUs, baseline);
317:   const hit = new Set<number>();
318:   for (const time of blunderTimes) {
319:     const index = periods.findIndex((period) => (time ?? -1) >= period.fromUs && (time ?? -1) <= period.toUs);
320:     if (index < 0) return undefined;
321:     hit.add(index);
322:     if (hit.size > 1) return undefined;
323:   }
324:   const period = periods[[...hit][0] ?? -1];
325:   if (!period) return undefined;
326:   return {
327:     elevatedMinutes: (period.toUs - period.fromUs) / 60_000_000,
328:     deltaBpm: Math.round(period.deltaBpm),
329:   };
330: }
