252:         for (let rest = moveIndex; rest < sans.length; rest += 1) {
253:           const when = moveTimes.find((time) => time.gameIndex === aligned.game.index && time.moveIndex === rest);
254:           const rawThink = thinks[rest] ?? null;
255:           metrics.push({
256:             cpl: null,
257:             accuracy: null,
258:             blunder: false,
259:             band: null,
260:             includeInStats: true,
261:           });
262:           timelineMoves.push({
263:             gameIndex: aligned.game.index,
264:             moveIndex: rest,
265:             san: sans[rest] ?? '',
266:             tUs: when?.tUs ?? null,
267:             cpl: null,
268:             thinkSec: rawThink !== null && rawThink >= 0 ? rawThink : null,
269:             blunder: false,
270:             band: null,
271:           });
272:         }
273:         break;
274:       }
275:       const when = moveTimes.find((time) => time.gameIndex === aligned.game.index && time.moveIndex === moveIndex);
276:       const before = await evaluate(position.fenBefore);
277:       const after = await evaluate(position.fenAfter);
278:       const band = when?.tUs === undefined || when.tUs === null ? null : bandAt(samples, when.tUs, baseline);
279:       const metric = scoreMove(before, after, band, aligned.game.includeInStats);
280:       if (metric.blunder && metric.band === 'elevated') elevatedBlunderTimes.push(when?.tUs ?? null);
281:       metrics.push(metric);
282:       const rawThink = thinks[moveIndex] ?? null;
283:       timelineMoves.push({
284:         gameIndex: aligned.game.index,
285:         moveIndex,
286:         san: sans[moveIndex] ?? '',
287:         tUs: when?.tUs ?? null,
288:         cpl: metric.cpl,
289:         thinkSec: rawThink !== null && rawThink >= 0 ? rawThink : null,
290:         blunder: metric.blunder,
291:         band: metric.band,
