39: export function downscaleRgbToRgba(
40:   source: Uint8Array,
41:   sourceWidth: number,
42:   sourceHeight: number,
43:   strideBytes: number,
44:   outWidth: number,
45: ): PreviewFrame {
46:   if (
47:     !Number.isInteger(sourceWidth) ||
48:     !Number.isInteger(sourceHeight) ||
49:     sourceWidth < 2 ||
50:     sourceHeight < 2
51:   ) {
