53:   }
54:   if (!Number.isInteger(strideBytes) || strideBytes < sourceWidth * 3) {
55:     throw new Error('The camera frame stride is too small for its width.');
56:   }
57:   if (source.byteLength < strideBytes * sourceHeight) {
58:     throw new Error('The camera frame is shorter than its size says.');
59:   }
