63:   const width = Math.max(MIN_PREVIEW_WIDTH, Math.round(sourceWidth * scale));
64:   const height = Math.max(2, Math.round(sourceHeight * scale));
65:   const rgba = new Uint8Array(width * height * 4);
66:   const xs = new Int32Array(width);
67:   for (let x = 0; x < width; x += 1) {
68:     xs[x] = Math.min(sourceWidth - 1, Math.floor(((x + 0.5) * sourceWidth) / width));
69:   }
70:   let lumaSum = 0;
71:   let out = 0;
72:   for (let y = 0; y < height; y += 1) {
73:     const sourceRow = Math.min(sourceHeight - 1, Math.floor(((y + 0.5) * sourceHeight) / height)) * strideBytes;
74:     for (let x = 0; x < width; x += 1) {
75:       const at = sourceRow + xs[x] * 3;
76:       const red = source[at];
77:       const green = source[at + 1];
78:       const blue = source[at + 2];
